package br.com.erp;
import br.com.erp.fiscal.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FiscalInfrastructureTest {
 private FiscalContext context(){return new FiscalContext(UUID.randomUUID(),UUID.randomUUID(),FiscalContext.Environment.HOMOLOGATION);}
 @Test void credentialsAreAuthenticatedAndBoundToBranchAndEnvironment(){var secrets=new FiscalSecrets(Base64.getEncoder().encodeToString(new byte[32]));var c=context();String encrypted=secrets.encrypt(c,"test-only-private-data");assertFalse(encrypted.contains("test-only-private-data"));assertEquals("test-only-private-data",secrets.decrypt(c,encrypted));assertThrows(Exception.class,()->secrets.decrypt(context(),encrypted));assertThrows(Exception.class,()->secrets.decrypt(new FiscalContext(c.tenantId(),c.branchId(),FiscalContext.Environment.PRODUCTION),encrypted));byte[] changed=Base64.getDecoder().decode(encrypted);changed[changed.length-1]^=1;assertThrows(Exception.class,()->secrets.decrypt(c,Base64.getEncoder().encodeToString(changed)));assertNotEquals(encrypted,secrets.encrypt(c,"test-only-private-data"));}
 @Test void missingOrInvalidMasterKeyCannotStoreCredentials(){assertThrows(Exception.class,()->new FiscalSecrets("").encrypt(context(),"x"));assertThrows(Exception.class,()->new FiscalSecrets("wrong-key").encrypt(context(),"x"));}
 @Test void xmlCannotResolveExternalEntitiesOrAcceptDoctype(){assertThrows(IllegalArgumentException.class,()->SefazXml.parse("<!DOCTYPE x [<!ENTITY e SYSTEM 'file:///C:/Windows/win.ini'>]><x>&e;</x>"));assertThrows(IllegalArgumentException.class,()->SefazXml.parse("<x>"));assertThrows(IllegalArgumentException.class,()->SefazXml.parse("x".repeat(SefazXml.MAX_BYTES+1)));}
 @Test void soapPreservesFiscalNamespaceAndRejectsFaults(){String payload="<consStatServ xmlns='"+SefazXml.NFE+"' versao='4.00'><tpAmb>2</tpAmb><cUF>52</cUF><xServ>STATUS</xServ></consStatServ>";var envelope=SefazXml.parse(SefazXml.soap(SefazEndpoints.Service.STATUS,payload));assertNotNull(SefazXml.unique(envelope,SefazXml.NFE,"consStatServ"));String response="<s:Envelope xmlns:s='"+SefazXml.SOAP+"'><s:Body><nfeResultMsg><retConsStatServ xmlns='"+SefazXml.NFE+"'><cStat>107</cStat></retConsStatServ></nfeResultMsg></s:Body></s:Envelope>";assertEquals("107",SefazXml.field(SefazXml.parse(SefazXml.response(response)).getDocumentElement(),"cStat"));assertThrows(IllegalArgumentException.class,()->SefazXml.response("<s:Envelope xmlns:s='"+SefazXml.SOAP+"'><s:Body><s:Fault/></s:Body></s:Envelope>"));}
 @Test void goEndpointAndQrCodeSeparateEnvironments(){assertEquals("homolog.sefaz.go.gov.br",SefazEndpoints.go(FiscalContext.Environment.HOMOLOGATION,SefazEndpoints.Service.AUTHORIZE).getHost());assertEquals("nfe.sefaz.go.gov.br",SefazEndpoints.go(FiscalContext.Environment.PRODUCTION,SefazEndpoints.Service.AUTHORIZE).getHost());assertTrue(SefazEndpoints.qrCode(FiscalContext.Environment.HOMOLOGATION).contains("nfewebhomolog"));assertTrue(SefazEndpoints.qrCode(FiscalContext.Environment.PRODUCTION).contains("nfeweb.sefaz"));}
 @Test void a1SignsXmlAndTamperingInvalidatesSignature(@org.junit.jupiter.api.io.TempDir java.nio.file.Path temp)throws Exception{
  var file=temp.resolve("test-only.p12");String password="fixture-only-password";var keytool=java.nio.file.Path.of(System.getProperty("java.home"),"bin","keytool.exe");if(!java.nio.file.Files.exists(keytool))keytool=java.nio.file.Path.of(System.getProperty("java.home"),"bin","keytool");
  var process=new ProcessBuilder(keytool.toString(),"-genkeypair","-alias","test","-dname","CN=Fiscal Test Only,O=Test,C=BR","-keyalg","RSA","-keysize","2048","-validity","1","-storetype","PKCS12","-keystore",file.toString(),"-storepass",password,"-keypass",password,"-noprompt","-ext","KU=digitalSignature","-ext","EKU=clientAuth").redirectErrorStream(true).redirectOutput(temp.resolve("keytool.txt").toFile()).start();assertTrue(process.waitFor(30,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,process.exitValue());byte[] pfx=java.nio.file.Files.readAllBytes(file);var cert=new FiscalCertificate(pfx,password.toCharArray());assertThrows(IllegalArgumentException.class,()->new FiscalCertificate(pfx,"wrong-password".toCharArray()));String xml="<NFe xmlns='"+SefazXml.NFE+"'><infNFe Id='NFe"+"1".repeat(44)+"' versao='4.00'><ide><cUF>52</cUF></ide></infNFe></NFe>";String signed=SefazSignature.sign(xml,"infNFe",cert.privateKey(password.toCharArray()),cert.certificate());assertTrue(validSignature(signed,cert));assertFalse(validSignature(signed.replace("<cUF>52</cUF>","<cUF>35</cUF>"),cert));assertThrows(IllegalArgumentException.class,()->SefazSignature.sign(signed,"infNFe",cert.privateKey(password.toCharArray()),cert.certificate()));
 }
 private boolean validSignature(String xml,FiscalCertificate certificate)throws Exception{var doc=SefazXml.parse(xml);SefazXml.unique(doc,SefazXml.NFE,"infNFe").setIdAttribute("Id",true);var signature=SefazXml.unique(doc,javax.xml.crypto.dsig.XMLSignature.XMLNS,"Signature");var context=new javax.xml.crypto.dsig.dom.DOMValidateContext(certificate.certificate().getPublicKey(),signature);context.setProperty("org.jcp.xml.dsig.secureValidation",false);return javax.xml.crypto.dsig.XMLSignatureFactory.getInstance("DOM").unmarshalXMLSignature(context).validate(context);}
 @Test void schemaImportsStayWithinInstalledBundle(@org.junit.jupiter.api.io.TempDir java.nio.file.Path temp)throws Exception{var root=java.nio.file.Files.createDirectory(temp.resolve("schemas"));java.nio.file.Files.writeString(root.resolve("simple.xsd"),"<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'><xs:element name='value' type='xs:int'/></xs:schema>");var schema=new SefazSchema(root);schema.validate("<value>42</value>","simple.xsd");assertThrows(IllegalArgumentException.class,()->schema.validate("<value>not-an-integer</value>","simple.xsd"));java.nio.file.Files.writeString(temp.resolve("outside.xsd"),"<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'/>");java.nio.file.Files.writeString(root.resolve("escape.xsd"),"<xs:schema xmlns:xs='http://www.w3.org/2001/XMLSchema'><xs:include schemaLocation='../outside.xsd'/></xs:schema>");assertThrows(IllegalArgumentException.class,()->schema.validate("<value>1</value>","escape.xsd"));assertThrows(IllegalArgumentException.class,()->schema.validate("<value>1</value>","../outside.xsd"));}
}
